sys_script.script:
(function executeRule(current, previous) {

    var missingFields = [];

    if (!current.event_name) {
        missingFields.push("Event Name");
    }

    if (!current.event_type) {
        missingFields.push("Event Type");
    }

    if (!current.technology_tags) {
        missingFields.push("Technology Tags");
    }

    if (!current.event_date) {
        missingFields.push("Event Date");
    }

    if (!current.registration_deadline) {
        missingFields.push("Registration Deadline");
    }

    if (!current.location) {
        missingFields.push("Location");
    }

    if (!current.organizer) {
        missingFields.push("Organizer");
    }

    if (missingFields.length > 0) {

        gs.addErrorMessage(
            "Please provide the following required information: " +
            missingFields.join(", ")
        );

        current.setAbortAction(true);
    }

})(current, previous);
